// ムチ一閃 web prototype — the app in the tone & manner of Codex's Figma screens (unity/design/figma-screens 01–18,
// generated by unity/design/export_figma_screens.py / export_monetization_screens.py; tokens in style.css), with the
// round 8 experience of docs/planning/06 (REQ-UXP-001..005) running on
//   - MuchiLogic: the real server domain code in the browser (consent, partner grant, gacha tables, naming rules, unlocks,
//     shop display data and offers, purchase-intent age checks, season pass, rewards, account deletion)
//   - MuchiRace:  the real C# race engine + Unity game layer in WebAssembly (TutorialDirector, RaceFeel, RaceDebrief,
//     RaceResultModel, RaceCameraRig, unique skills of ruleset 1.3.0)
// Round 9 (06 §7 item 12 / §7.3): the replay share card (ReplayClip / ShareCard / ReplayShareModel), the account-link
// prompt (AccountLinkPrompt) and the time attack ghost picker with the friend tab (GhostPicker, GhostPlayer).
// Nothing on these screens is a made-up number: every value comes from one of the two.
//
// Layout: the 1600×900 stage of the Unity CanvasScaler; Codex's 1672×941 frames are placed at ×0.957. One idea per
// view: photoreal key art full-bleed, one translucent navy panel, one cyan CTA; secondary information lives in sheets.
import { RaceView } from './race-view.js';

const L = globalThis.MuchiLogic;
const $screens = document.getElementById('screens');
const $stage = document.getElementById('stage');
const $canvas = document.getElementById('race-canvas');

// ---------------------------------------------------------------- colour tokens (style.css :root)
const CYAN = 'var(--cyan)', GOLD = 'var(--gold)', WHITE = 'var(--white)', MUTED = 'var(--text-2)', SOFT = 'var(--text-3)', DIM = 'var(--text-4)';
const RED = 'var(--danger)', WARN = 'var(--warn)', OK = 'var(--ok)', VIOLET = 'var(--violet)';

// ---------------------------------------------------------------- persistence (PlayerPrefs keys of the Unity build)
const prefs = {
  get(k, d) { try { const v = localStorage.getItem(k); return v === null ? d : v; } catch { return d; } },
  set(k, v) { try { localStorage.setItem(k, String(v)); } catch { /* private mode */ } },
  int(k, d) { const v = parseInt(this.get(k, ''), 10); return Number.isFinite(v) ? v : d; },
};
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

// ---------------------------------------------------------------- localisation (LocaleService; Japanese is the default)
let JA = {};
const EXTRA_JA = {
  'SCOUT RATES': '提供割合', 'RARITY TOTALS': 'レア度ごとの合計', 'EACH HORSE': '馬ごとの提供割合',
  '10TH PULL GUARANTEE (SR+)': '10連の10枠目（SR以上確定）', 'PITY': '天井', 'pulls → exchange': '回で交換', 'PICKUP': 'ピックアップ', 'STEP-UP': 'ステップアップ',
  'Generated from the same table used for drawing (server master).': '抽選と同じ表（サーバーのマスターデータ）から自動生成しています。',
};
const isJa = () => prefs.get('muchi.language', 'ja') === 'ja';
const T = (s) => (s == null ? s : isJa() ? (JA[s] ?? EXTRA_JA[s] ?? s) : s);

// ---------------------------------------------------------------- English (REQ-L10N-013, contracts/protocol.md §23)
// The screens build Japanese (the source language, like the server and the Unity game layer). With EN on, every text
// node on the stage goes through MuchiLogic.l10n: the server's English (master/locale-en.json + i18n/en.ts — the same
// strings a request with Accept-Language: en gets), the game layer's (ui-en.json) and this prototype's (proto-en.json).
// Katakana horse names come back romanized. Text that does not fit its box is shrunk (fitText). Legal pages under
// Japanese law stay Japanese with an English courtesy note (.keep-ja).
const JP_RE = /[\u3040-\u30ff\u3400-\u9fff\u3000-\u303f\uff01-\uff60]/;
const l10nMisses = new Map();
function enText(s) {
  if (!s || !JP_RE.test(s)) return s;
  const m = /^(\s*)([\s\S]*?)(\s*)$/.exec(s);
  const t = L.l10n.translate(m[2]);
  if (t == null) { l10nMisses.set(m[2], (l10nMisses.get(m[2]) ?? 0) + 1); return s; }
  return m[1] + t + m[3];
}
const EN_LEGAL_NOTE = 'This notice is required by Japanese law and is provided in Japanese, the language that applies. The English below is a courtesy translation only; it has no legal effect and does not extend these terms outside Japan.';
const keepJa = (n) => !!(n.parentElement ?? n).closest?.('.keep-ja');
function translateTree(n) {
  if (n.nodeType === 3) { if (!keepJa(n)) { const v = enText(n.nodeValue); if (v !== n.nodeValue) n.nodeValue = v; } return; }
  if (n.nodeType !== 1 || n.classList?.contains('keep-ja')) return;
  if (n.placeholder && JP_RE.test(n.placeholder)) n.placeholder = enText(n.placeholder);
  n.childNodes.forEach(translateTree);
}
let fitPending = false;
const l10nObserver = new MutationObserver((muts) => {
  if (isJa() && textScale() === 1) return;
  if (!isJa()) {
    for (const m of muts) {
      if (m.type === 'characterData') translateTree(m.target);
      else m.addedNodes.forEach(translateTree);
    }
  }
  if (!fitPending) { fitPending = true; requestAnimationFrame(() => { fitPending = false; scaleText(cur); fitText(cur); }); }
});
/**
 * English is longer than Japanese, and the larger text sizes (round 15, REQ-A11Y-005) are larger than the layout: a
 * text that overflows its box (wider than its element, taller than a fixed height, or below the bottom of its panel)
 * is set smaller, in 5.7 % steps — never below its standard size in Japanese, down to 66 % of it in English.
 * Japanese at the standard size is never touched.
 */
/** Line boxes of a text (distinct tops of its client rects). */
function lineCount(x) { const r = document.createRange(); r.selectNodeContents(x); return new Set([...r.getClientRects()].filter((c) => c.width > 0).map((c) => Math.round(c.top))).size; }
const rangeRect = (x) => { const r = document.createRange(); r.selectNodeContents(x); return r.getBoundingClientRect(); };
/** Two texts' glyph boxes cover each other (more than 4 px across and 30 % of the shorter one's height). */
function textsCollide(a, b, k) {
  const w = Math.min(a.right, b.right) - Math.max(a.left, b.left), h = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
  return w > 4 * k && h > .3 * Math.min(a.height, b.height);
}
function fitText(root) {
  const ja = isJa();
  if ((ja && textScale() === 1) || !root) return;
  const els = root.querySelectorAll('.label, .kicker, .caption, .btn, .pill, .tag');
  // round 15: at the larger text sizes a text may also run into its neighbour (a title into its subtitle, a section
  // label into the first row) — outside the race HUD (repainted every frame) such a text is brought back too
  const k = $stage.getBoundingClientRect().width / 1600;
  const neighbours = textScale() > 1 && !root.classList.contains('race') ? [...els].filter((x) => x.offsetParent !== null && x.textContent.trim()) : [];
  const collides = (e) => {
    if (!neighbours.length) return false;
    const a = rangeRect(e);
    if (!a.width) return false;
    for (const o of neighbours) {
      if (o === e || o.contains(e) || e.contains(o)) continue;
      if (textsCollide(a, rangeRect(o), k)) return true;
    }
    return false;
  };
  for (const e of els) {
    if (e.offsetParent === null) continue;
    const isBtn = e.classList.contains('btn');
    const spans = isBtn ? [...e.querySelectorAll(':scope > span')] : [];
    const host = isBtn ? null : e.parentElement?.closest('.glass, .card, .sheet, .btn');
    const text = () => { const r = document.createRange(); r.selectNodeContents(e); return r.getBoundingClientRect(); };
    const over = () => e.scrollWidth > e.clientWidth + 1 || (e.style.height && e.scrollHeight > e.clientHeight + 1)
      || (host && !host.classList.contains('btn') && text().bottom > host.getBoundingClientRect().bottom + 1)
      || text().right > $stage.getBoundingClientRect().right + 1 || collides(e)
      || (isBtn && spans.some((x) => x.dataset.tl && lineCount(x) > +x.dataset.tl));
    // fit again from the base size (a sheet measured mid slide-in must not stay 'overflow' once it has settled)
    const setSize = (px) => { if (isBtn) spans.forEach((x) => { x.style.fontSize = px; }); else e.style.fontSize = px; };
    if (e.dataset.fitBase) { setSize(e.dataset.fitBase + 'px'); delete e.dataset.fit; }
    if (!over()) continue;
    const sized = isBtn ? spans[0] ?? e : e;
    const base = parseFloat(e.dataset.fitBase ?? getComputedStyle(sized).fontSize);
    e.dataset.fitBase = String(base);
    const std = parseFloat(sized.dataset.ts) || base; // the standard-size font (before the text size step)
    const floor = ja ? std : std * .66;
    for (let k = 1; k <= 12 && over(); k++) {
      const px = Math.max(floor, base * (1 - .057 * k));
      setSize(px.toFixed(1) + 'px');
      if (px <= floor) break;
    }
    e.dataset.fit = over() ? 'overflow' : 'shrunk';
  }
}
/** The screens' language: html lang (CSS), the observer, and the commentary language of the next race. */
let enTables = null;
function applyLanguage() {
  document.documentElement.lang = isJa() ? 'ja' : 'en';
  if (engine && enTables) engine.SetLanguage(isJa() ? 'ja' : 'en', isJa() ? enTables.commentaryJa : enTables.commentaryEn, enTables.server, enTables.ui);
}

// ---------------------------------------------------------------- round 15: アクセシビリティ設定 (REQ-A11Y-*, protocol §41)
// Mirrors unity/Assets/Muchi/Game/AccessibilityModel.cs: the account's settings on the real server rules (MuchiLogic), a
// device copy applied from the first frame (and offline), and the values every screen honours: the text size step
// (body text < 28 px ×1.15 / ×1.3, scaleText), the colour mode (html[data-color-mode] swaps the --a11y-* tokens of
// contracts/a11y-tokens.json), reduce motion (html[data-reduce-motion]: no drift / shake / speed lines / blinking, short
// transitions, the scout reveal without its glow wait), haptics, subtitles, the one-handed race layout and the whip hold.
const A11Y_KEY = 'muchi.a11y.settings', A11Y_DIRTY = 'muchi.a11y.dirty';
const A11Y_DEFAULTS = { textSize: 'standard', colorMode: 'standard', reduceMotion: false, haptics: true, subtitles: true, oneHanded: 'off', whipInput: 'tap' };
const A11Y_SCALE = { standard: 1, large: 1.15, largest: 1.3 };
let a11y = (() => { try { return { ...A11Y_DEFAULTS, ...JSON.parse(prefs.get(A11Y_KEY, '{}')) }; } catch { return { ...A11Y_DEFAULTS }; } })();
const textScale = () => A11Y_SCALE[a11y.textSize] ?? 1;
const reduced = () => !!a11y.reduceMotion;
function applyA11y() {
  const d = document.documentElement.dataset;
  d.textSize = a11y.textSize; d.colorMode = a11y.colorMode; d.reduceMotion = a11y.reduceMotion ? 'on' : 'off';
  d.oneHanded = a11y.oneHanded; d.whipInput = a11y.whipInput;
  if (engine) engine.SetWhipInput(a11y.whipInput);
}
function storeA11y(v, dirty) {
  a11y = { ...A11Y_DEFAULTS, ...Object.fromEntries(Object.keys(A11Y_DEFAULTS).map((k) => [k, v[k] ?? A11Y_DEFAULTS[k]])) };
  prefs.set(A11Y_KEY, JSON.stringify({ ...a11y, rev: v.rev ?? 0 })); prefs.set(A11Y_DIRTY, dirty ? '1' : '0');
  applyA11y();
}
/** REQ-A11Y-004: an unsent device change wins; otherwise the account's value replaces the device copy. */
async function syncA11y() {
  if (prefs.get(A11Y_DIRTY, '0') === '1') { const r = await L.setAccessibility({ ...a11y }); if (r.ok) storeA11y(r.value, false); return; }
  storeA11y(await L.accessibility(), false);
}
async function setA11y(key, value) {
  const next = { ...a11y, [key]: value };
  storeA11y(next, true); // applied at once (and kept if the save fails)
  const r = await L.setAccessibility(next);
  if (r.ok) storeA11y(r.value, false);
  toast(r.ok ? 'アクセシビリティ設定を保存しました' : 'オンラインになったら保存します');
}
/**
 * REQ-A11Y-005: the text size step on every text of the stage. Each text keeps its standard size in data-ts and body
 * text (< 28 px) is set ×1.15 / ×1.3; headings and big numbers stay. fitText then brings back, towards the standard
 * size and never below it, only what does not fit its box.
 */
const SCALE_SEL = '.label, .kicker, .caption, .btn > span, .pill, .tag, .qc-scale, .toast, .stamina .t, .stamina .s, .whipdots b, .marker .nm, .marker .gap, .marker .wind';
function scaleText(root) {
  const k = textScale();
  if (k === 1 || !root) return;
  for (const e of root.querySelectorAll(SCALE_SEL)) {
    if (e.dataset.ts) continue;
    if (e.closest('.btn.whip')) { e.dataset.ts = '0'; continue; } // the whip's label is sized to its ring (like an icon)
    const base = parseFloat(getComputedStyle(e).fontSize);
    e.dataset.ts = String(base);
    if (e.parentElement?.classList.contains('btn')) e.dataset.tl = String(lineCount(e)); // a button label must not start wrapping
    if (base < 28) e.style.fontSize = (base * k).toFixed(1) + 'px';
  }
}
/** REQ-A11Y-009: every vibration goes through here (off = none at all). */
function haptic(pattern) { if (!a11y.haptics) return; try { navigator.vibrate?.(pattern); } catch { /* not supported */ } }
/** REQ-A11Y-008: one-shot lights — at most 3 in any one-second window (the 4th shows its text without the light). */
const flashTimes = [];
function flashOk(now = performance.now()) {
  while (flashTimes.length && now - flashTimes[0] >= 1000) flashTimes.shift();
  if (flashTimes.length >= 3) return false;
  flashTimes.push(now); return true;
}

// ---------------------------------------------------------------- round 19: 画質・省電力・通信量 (REQ-PERF-*, protocol §56)
// Mirrors unity/Assets/Muchi/Game/PerformanceSettingsModel.cs: four device-only settings (never sent to the server), the
// device class from what the browser reports, and the real Muchi.Client RenderProfile (WASM PerfResolve) deciding what the
// prototype draws: the 3D view's pixel ratio and shadows (RaceView.setQuality), the race loop's frame cap, the whip's
// speed lines and FOV kick, and the home art's slow drift (html[data-perf-ambient]). The engine never sees any of it.
const PERF_KEY = 'muchi.perf.settings', PERF_NET_KEY = 'muchi.perf.demoNet', PERF_STORE_KEY = 'muchi.perf.demoStorage';
let perf = (() => { try { return JSON.parse(prefs.get(PERF_KEY, '{}')) || {}; } catch { return {}; } })();
const perfSettings = () => ({ graphics: perf.graphics ?? 'auto', frameRate: perf.frameRate ?? 'auto', batterySaver: perf.batterySaver === true, dataSaver: perf.dataSaver === true });
const perfWire = (s, k) => (k === 'batterySaver' || k === 'dataSaver' ? (s[k] ? 'on' : 'off') : s[k]);
let perfDevice = null, perfNow = null;
/** REQ-PERF-002: memory, cores and a software renderer from the browser → DeviceClassifier (once). */
function perfDeviceInfo() {
  if (perfDevice) return perfDevice;
  const profile = { memoryMb: Math.round((navigator.deviceMemory ?? 4) * 1024), cores: navigator.hardwareConcurrency ?? 4, gpuMb: 0, software: !!view?.lite, refreshHz: 60 };
  if (!engine) return { profile, deviceClass: 'mid' };
  const info = { profile, deviceClass: engine.PerfClassify(JSON.stringify(profile)) };
  if (view?.renderer) perfDevice = info; // decided once the renderer is known (software GL → low)
  return info;
}
function perfProfile(inRace, settings = perfSettings()) {
  if (!engine) return null;
  return JSON.parse(engine.PerfResolve(JSON.stringify(settings), JSON.stringify({ deviceClass: perfDeviceInfo().deviceClass, inRace, lowPower: false, reduceMotion: reduced(), refreshHz: 60 })));
}
/** Applies the profile in force now (menus or the race). */
function applyPerf() {
  perfNow = perfProfile(raceActive);
  const d = document.documentElement.dataset;
  d.perfAmbient = perfNow && !perfNow.ambientMotion ? 'off' : 'on';
  d.perfTier = perfNow?.tier ?? 'medium';
  if (perfNow && view?.renderer) view.setQuality(perfNow);
}
/** A settings button: stored on the device at once; perf_setting_change only for a real change (REQ-PERF-015). */
function setPerf(key, value) {
  const before = perfSettings();
  const next = { ...before, [key]: key === 'batterySaver' || key === 'dataSaver' ? value === 'on' : value };
  if (perfWire(next, key) === perfWire(before, key)) return false;
  perf = next; prefs.set(PERF_KEY, JSON.stringify(next));
  (globalThis.__muchiKpi ??= []).push({ name: 'perf_setting_change', setting: key, value, deviceClass: perfDeviceInfo().deviceClass });
  applyPerf();
  return true;
}
// The storage screen's demo catalog (the server's platform view shape; the prototype downloads nothing): required boot /
// ftue files, optional venues, a coat and a banner with low variants, on-demand voice names. Hashes are made up.
const demoSha = (s) => { let h = 2166136261 >>> 0, out = ''; for (let k = 0; out.length < 64; k++) { for (const c of s + k) h = Math.imul(h ^ c.charCodeAt(0), 16777619) >>> 0; out += h.toString(16).padStart(8, '0'); } return out.slice(0, 64); };
const DEMO_ASSETS = [
  ['horse/coat/default', 'boot', true, 180_000], ['sfx/race/default', 'boot', true, 60_000], ['sfx/race/whip', 'ftue', true, 90_000],
  ['scene/venue/aoba', 'ftue', false, 24_000_000, 8_000_000], ['scene/venue/minato', 'race', false, 38_000_000, 12_500_000], ['scene/venue/kirameki', 'race', false, 41_000_000, 13_000_000],
  ['horse/coat/bay', 'home', false, 6_200_000, 2_100_000], ['banner/gacha/standard', 'shop', false, 3_400_000, 1_100_000],
  ['voice/ja/name/n0000000000000001', 'ondemand', false, 260_000], ['voice/ja/name/n0000000000000002', 'ondemand', false, 240_000],
];
const DEMO_CATALOG = JSON.stringify({
  catalogVersion: 5, manifestVersion: 2, platform: 'ios', hash: 'demo5', baseUrl: 'https://assets.example.com', urlTemplate: '{base}/{platform}/{sha256}/{file}',
  entries: DEMO_ASSETS.map(([key, group, required, size, low]) => ({ key, file: key + '.bundle', sha256: demoSha(key), size, group, required, ...(low ? { low: { file: key + '.low.bundle', sha256: demoSha(key + '.low'), size: low } } : {}) })),
});
/** What is "on the device": the required files, the tutorial venue and the coat already preloaded, a partial file, an old version. */
function storageState() {
  try { const s = JSON.parse(prefs.get(PERF_STORE_KEY, 'null')); if (s?.blobs) return s; } catch { /* reset below */ }
  const blobs = {};
  for (const [key, , , size] of DEMO_ASSETS.slice(0, 4)) blobs[demoSha(key)] = size;
  blobs[demoSha('horse/coat/bay')] = 6_200_000;
  blobs[demoSha('scene/venue/aoba@old')] = 2_300_000;
  return { blobs, partial: 1_200_000 };
}
const saveStorage = (s) => prefs.set(PERF_STORE_KEY, JSON.stringify(s));
const storageReport = (s = storageState()) => JSON.parse(engine.StorageReport(DEMO_CATALOG, JSON.stringify(s.blobs), s.partial, perfSettings().dataSaver));
const demoNet = () => prefs.get(PERF_NET_KEY, 'wifi');

// ---------------------------------------------------------------- art (Unity Resources paths → site files)
let ART = {};
const art = (res) => ART[res] || '';

// ================================================================= design system (Codex's export_figma_screens.py)
let cur = null, currentScreen = null, timers = [];
function Clear(name) {
  raceActive = false;
  timers.forEach((t) => clearInterval(t)); timers = [];
  const next = document.createElement('div');
  next.className = 'screen';
  if (name) next.dataset.screen = name;
  $screens.appendChild(next);
  const prev = [...$screens.children].filter((c) => c !== next);
  prev.forEach((p) => { p.classList.add('out'); p.classList.remove('in'); setTimeout(() => p.remove(), 340); });
  requestAnimationFrame(() => requestAnimationFrame(() => next.classList.add('in')));
  cur = next;
  $canvas.hidden = true;
  globalThis.__muchi && (globalThis.__muchi.screen = name ?? '');
  if (engine) applyPerf(); // round 19: menus get the menu profile (the battery saver's 30 fps / no drift)
}
const every = (ms, f) => { f(); timers.push(setInterval(f, ms)); };
function el(cls, x, y, w, h, parent) {
  const d = document.createElement('div');
  d.className = 'el ' + cls;
  Object.assign(d.style, { left: x + 'px', top: y + 'px', width: w + 'px' });
  if (h != null) d.style.height = h + 'px';
  (parent || cur).appendChild(d);
  return d;
}
/** A plain rectangle (only for gauges and hit areas); panels are Glass. */
function Panel(name, x, y, w, h, color, parent) { const d = el('panel', x, y, w, h, parent); d.style.background = color; d.dataset.name = name; return d; }
/** box(): the deep navy translucent panel (opacity .77–.95, rx 4, soft blur). */
function Glass(name, x, y, w, h, parent, a) { const d = el('glass', x, y, w, h, parent); d.dataset.name = name; if (a != null) d.style.setProperty('--a', a); return d; }
/** card(): a navy card with a 4 px accent line on top (cyan, gold or a coat colour). */
function Card(name, x, y, w, h, parent, accent) { const d = el('card', x, y, w, h, parent); d.dataset.name = name; if (accent) d.style.setProperty('--accent', accent); return d; }
/** Text. Weight follows the role: 700 for headings and numbers (≥ 30 px), 400 for body; pass o.weight to choose. */
function Txt(text, x, y, w, size, color, parent, o = {}) {
  const d = el('label ' + (o.cls ?? ''), x, y, w, o.h ?? null, parent);
  d.textContent = text ?? '';
  d.style.fontSize = size + 'px';
  if (color) d.style.color = color;
  d.classList.add('w' + ((o.weight ?? (size >= 30 ? 700 : 400)) / 100));
  if (o.ls) d.style.letterSpacing = o.ls;
  if (o.align) d.style.textAlign = o.align;
  if (o.lh) d.style.lineHeight = o.lh;
  if (o.nowrap) d.classList.add('nowrap');
  return d;
}
/** Section label: the 86×3 cyan rule and the letter-spaced cyan caption under it (「01 / はじめての相棒」). */
function Kicker(text, x, y, parent, o = {}) {
  if (o.rule !== false) { const r = el('rule', x, y, o.ruleW ?? 86, 3, parent); if (o.gold) r.classList.add('gold'); }
  const k = el('label kicker', x, y + (o.rule === false ? 0 : 38), o.w ?? 560, null, parent);
  k.textContent = text; k.style.fontSize = (o.size ?? 18) + 'px';
  if (o.color) k.style.color = o.color;
  return k;
}
function Caption(text, x, y, parent, size = 15, color) { const c = el('label caption', x, y, 900, null, parent); c.textContent = text; c.style.fontSize = size + 'px'; if (color) c.style.color = color; return c; }
const Hair = (x, y, w, parent) => el('hair', x, y, w, 1, parent);
function Gauge(x, y, w, frac, parent, o = {}) {
  const b = el('bar' + (o.gold ? ' gold' : '') + (o.thick ? ' thick' : ''), x, y, w, null, parent);
  const i = document.createElement('i'); i.style.width = Math.round(100 * clamp(frac, 0, 1)) + '%'; b.appendChild(i);
  return b;
}
function Btn(value, x, y, w, h, action, cls = '', parent, text) {
  const d = el('btn ' + cls, x, y, w, h, parent);
  const bg = document.createElement('div'); bg.className = 'bg'; d.appendChild(bg);
  const s = document.createElement('span'); s.textContent = text ?? T(value); d.appendChild(s);
  d.dataset.label = value;
  d.setAttribute('role', 'button');
  d.addEventListener('click', (e) => { if (d.classList.contains('disabled')) return; e.stopPropagation(); action(); });
  return d;
}
/** btn(): the primary CTA — cyan parallelogram, slanted bottom-left, top highlight and 「»」. One per view. */
const Cta = (value, x, y, w, action, parent, cls = '') => Btn(value, x, y, w, cls.includes('small') ? 60 : 73, action, 'cta ' + cls, parent);
/** compact_btn(): secondary action — navy with a 2 px cyan stroke. */
