const DEX_INCLUDED = ['プロフィール・設定（アクセシビリティを含む）', '馬・アイテム・プレゼント', '有償コインと無償コインの残高と履歴（別々に記載）', '購入とスカウトの記録', 'フレンド・ブロック・自分が送った通報', 'お知らせ・リプレイと写真の記録・カップ・振り返り', '登録した端末・分析イベント'];
