  const p = Glass('Odds frame', 36, 134, 1528, 676, undefined, .93);
  const rows = (title, totals, x, y) => {
    Kicker(T(title), x, y, p, { rule: false, size: 14 });
    Object.entries(totals).forEach(([r, v], i) => { Txt(`${RARITY_SHAPE[r]} ${r}`, x, y + 30 + i * 30, 110, 17, r === 'SSR' ? GOLD : r === 'SR' ? CYAN : WHITE, p, { weight: 700 }); Txt(v.rate, x + 120, y + 30 + i * 30, 160, 17, WHITE, p, { cls: 'num', weight: 500 }); });
  };
  rows('RARITY TOTALS', o.rarityTotals, 36, 30);
