  const pity = Txt(`${o.pity.pullsRequired} ${T('pulls → exchange')}（${o.pity.label}）\n${o.pity.targets.map(templateName).join(' / ')}\n最大 ${fmt(o.pity.costCoins)}コイン（≈ ${yen(o.pity.estimatedMaxCostYen)}）`, 36, 358, 400, 15, WHITE, p, { weight: 500, lh: 1.6 });
  pity.dataset.pityCost = String(o.pity.costCoins);
  if (o.pity.carryOver) Txt(o.pity.carryOver.notice, 36, 470, 400, 13, WARN, p, { lh: 1.5 }).dataset.carryOver = '1';
  else Txt('この天井は期間で閉じません。', 36, 470, 400, 13, MUTED, p); // round 15: below the 4-line pity text (it ran into it at the standard size too)
  if (o.limitedNotice) Txt(o.limitedNotice, 36, 540, 400, 12, SOFT, p, { lh: 1.5 });
  Kicker(T('EACH HORSE'), 484, 30, p, { rule: false, size: 14 });
  const items = [...o.items].sort((a, b) => rarityRank(b.rarity) - rarityRank(a.rarity) || b.ppm - a.ppm);
  items.forEach((r, i) => {
    const colIdx = Math.floor(i / 17), row = i % 17;
    if (colIdx > 1) return;
    const x = 484 + colIdx * 330, y = 62 + row * 32;
    Txt(`${RARITY_SHAPE[r.rarity]} ${r.rarity}`, x, y, 70, 14, r.rarity === 'SSR' ? GOLD : r.rarity === 'SR' ? CYAN : WHITE, p, { weight: 700 });
    Txt(r.name + (r.limited ? '（限定）' : '') + (o.pickup?.templateId === r.templateId ? '★PU' : ''), x + 70, y, 180, 14, WHITE, p, { nowrap: true, weight: 500 });
    Txt(r.rate, x + 240, y, 76, 14, MUTED, p, { align: 'right', cls: 'num' });
  });
  // right column: the pickup's own rate, the step-up steps, legal pages
  let y = 30;
  if (o.pickup) {
    Kicker(T('PICKUP'), 1170, y, p, { rule: false, size: 14 });
    Txt(`${o.pickup.name}（${o.pickup.rarity}）\n1〜10枠目：${o.pickup.rate}\n10枠目の保証：${o.pickup.guaranteeRate}`, 1170, y + 28, 330, 15, WHITE, p, { weight: 500, lh: 1.6 }).dataset.pickupRate = o.pickup.rate;
    y += 120;
  }
  if (o.stepUp) {
    Kicker(T('STEP-UP'), 1170, y, p, { rule: false, size: 14 });
    o.stepUp.steps.forEach((s, i) => {
      const totals = s.finalSlot.rarityTotals ? Object.entries(s.finalSlot.rarityTotals).map(([r, v]) => `${r} ${v.rate}`).join(' ') : 'SR以上の保証（左の表）';
      Txt(`ステップ${s.step}　10連 ${fmt(s.priceTen)}　10枠目：${totals}`, 1170, y + 28 + i * 28, 330, 12, s.finalSlot.items ? GOLD : WHITE, p, { nowrap: false }).dataset.step = String(s.step);
    });
    y += 28 + o.stepUp.steps.length * 28 + 8;
    Txt(o.stepUp.notice, 1170, y, 330, 12, SOFT, p, { lh: 1.5 });
  }
  const legal = (L.legalLinks ?? []).filter((l) => l.key.startsWith('legal.'));
  legal.forEach((l, i) => TextLink(l.title, 1170, 560 + i * 44, 330, () => Legal(l.key === 'legal.tokushoho' ? 'tokushoho' : 'shikin', () => Odds(bannerId)), p));
