  const cols = type === 'color' ? [hexRgb(part.hex)] : [design.colors[0], design.colors[1], design.colors[2] ?? design.colors[0]].map((id) => hexRgb(hexOf(id) ?? '#888888'));
  const capc = design.capColors.map((id) => hexRgb(hexOf(id) ?? '#888888'));
