// ================================================================= round 16: シーズンの振り返り (REQ-RECAP-*, contracts/protocol.md §43)
// The recap the server froze at the season close (and at the game year's end, 04:00 JST on 1 January), stepped through one page
// at a time: photoreal art, a letter-spaced cyan label, one big number, a few notes, one skewed cyan CTA ». Every line comes from
// the server (seasonRecap.ts); horse names are what the player typed (keep-ja, never translated). Mirrors
// unity/Assets/Muchi/Game/SeasonRecapModel.cs. Share cards go through the same card idea as the replay share (watermark
// 「ムチ一閃」, #ムチ一閃), with 「順位を隠す」. No coin, purchase or betting word anywhere.
const RC_ART = { races: 'Art/first-ride', wins: 'Art/race-result', best_finish: 'Art/race-result', rank: 'Art/title-screen', horse: 'Art/partner-naming',
  time_attack: 'Art/first-ride', style: 'Art/home-paddock', rival: 'Art/race-result', team: 'Art/home-paddock', hall: 'Art/scout-reveal', replays: 'Art/first-ride', moments: 'Art/race-result', end: 'Art/title-screen' };
const RC_HIDE_KEY = 'muchi.recap.hideRank';
/**
 * §41 hook (accessibility, Round 15 — not on this base yet): "reduce motion" will come from the accessibility setting. Until then
 * the OS preference and a local key stand in. When on: pages cut instead of sliding, numbers do not count up.
 */
// Round 16 integration: the real §41 setting (その他 / アクセシビリティ 「動きを減らす」) or the OS preference — not a separate key
const rcReducedMotion = () => reduced() || !!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const rcTyped = (node) => { node.classList.add('keep-ja', 'typed'); node.dataset.typed = '1'; return node; };

async function Recaps() {
  currentScreen = Recaps;
  const r = await L.recap.list();
  if (!r.ok || !r.value.enabled) { toast('振り返りは今は表示できません'); Home(); return; }
  const v = r.value;
  Clear('recaps'); SetArt('Art/title-screen', false); Shade('left');
  TopBar('シーズンの振り返り', 'シーズンと1年の終わりに届きます　·　確定したレースの記録だけでできています', { wallet: false });
  const lp = Glass('Recap list', 36, 134, 820, 676, undefined, .88);
  lp.classList.add('rc-list');
  Kicker(`振り返り　/　${v.recaps.length}件`, 36, 30, lp);
  if (!v.recaps.length) Txt('振り返りは、シーズンが終わるとここに届きます', 36, 110, 748, 16, MUTED, lp, { lh: 1.6 }).classList.add('rc-empty');
  v.recaps.slice(0, 4).forEach((x, i) => {
    const c = Card('Recap card', 36, 100 + i * 136, 748, 120, lp, x.kind === 'year' ? 'var(--gold)' : 'var(--cyan)');
    c.classList.add('rc-card'); c.dataset.recap = x.id; c.dataset.opened = String(x.opened);
    Txt(x.title, 24, 22, 520, 26, WHITE, c, { weight: 700, nowrap: true, ls: '.04em' });
    Txt(x.kind === 'year' ? '1年の振り返り' : x.short ? '短い版（レースが少なかったシーズン）' : 'シーズンの振り返り', 24, 66, 520, 15, x.kind === 'year' ? GOLD : SOFT, c, { weight: 500, nowrap: true });
    if (!x.opened) Txt('NEW', 640, 24, 84, 15, CYAN, c, { weight: 700, ls: '.2em', align: 'right' }).classList.add('rc-new');
    Txt(x.completed ? '見終わりました' : '開く ›', 560, 70, 164, 14, x.completed ? DIM : CYAN, c, { weight: 700, align: 'right', nowrap: true });
    c.style.cursor = 'pointer'; c.addEventListener('click', () => Recap(x.id));
  });
  const rp = Glass('Recap notes', 880, 134, 684, 676, undefined, .84);
  Kicker('振り返りについて', 36, 30, rp);
  Txt('ランク戦のシーズンが終わるたびと、1年の終わりに1つずつ届きます。', 36, 110, 612, 17, WHITE, rp, { weight: 500, lh: 1.6 });
  Txt('中身はサーバーが確定させた記録だけです。推定や作り話は入りません。記録が途中から始まった時は、その日付を書きます。', 36, 190, 612, 15, SOFT, rp, { lh: 1.7 });
  Txt('共有カードに入るのは、あなたの馬の名前と数字だけです', 36, 300, 612, 15, SOFT, rp, { lh: 1.7 });
  if (v.unseen) Cta('新しい振り返りを見る', 36, 560, 612, () => Recap(v.unseen), rp).classList.add('rc-open-new');
  Back(Stable, 'BACK', 40, 834);
}

async function Recap(id, i = 0) {
  const r = await L.recap.view(id);
  if (!r.ok) { toast('振り返りは今は表示できません'); Recaps(); return; }
  const v = r.value;
  if (i === 0 && !v.openedAt) await L.recap.progress(id, 'open'); // recap_open (the server keeps the first time)
  i = clamp(i, 0, v.steps.length - 1);
  const st = v.steps[i];
  const last = i === v.steps.length - 1;
  if (last && !v.completedAt) await L.recap.progress(id, 'complete'); // recap_complete
  currentScreen = () => Recap(id, i);
  const reduced = rcReducedMotion();
  Clear('recap'); SetArt(RC_ART[st.key] ?? 'Art/race-result', !reduced); Shade('left');
  cur.dataset.step = st.key; cur.dataset.index = String(i); cur.dataset.reduced = String(reduced);
  if (reduced) cur.classList.add('rc-reduced');
  // the page counter: one thin bar per page
  const bars = el('rc-bars', 64, 40, 900, 4);
  v.steps.forEach((_, k) => { const b = el('rc-bar' + (k <= i ? ' on' : ''), k * (900 / v.steps.length), 0, 900 / v.steps.length - 6, 4, bars); b.dataset.k = String(k); });
  Kicker(`${v.title}　/　RECAP`, 64, 70, undefined, { w: 900, size: 17 });
  // the label sits clear of the big number's line box (its glyphs reach ~30 px above the box): 206, not 236 — at the
  // largest text size the two ran into each other (Round 16 integration, a11y-flow)
  const label = Txt(st.label, 64, st.key === 'end' ? 330 : 206, 960, st.key === 'end' ? 54 : 22, st.key === 'end' ? WHITE : CYAN, undefined, { weight: 700, ls: st.key === 'end' ? '.04em' : '.32em' });
  label.classList.add('rc-label');
  // the big text: a number counts up (unless reduced motion), a class / time / place shows as is, a horse name as typed
  const big = st.value ?? st.horseName ?? null;
  if (big !== null) {
    const isName = st.value === null && st.horseName != null;
    // the number and its unit in one line (spans), so the unit always sits right after the final number
    const node = Txt('', 64, 282, 1000, isName ? 96 : 168, isName ? WHITE : GOLD, undefined, { weight: 700, cls: isName ? '' : 'num', nowrap: true, ls: isName ? '.04em' : '0' });
    const num = document.createElement('span'); num.textContent = big; num.className = 'rc-num'; node.appendChild(num);
    node.classList.add('rc-big'); node.dataset.final = big;
    if (isName) rcTyped(node);
    if (st.unit) {
      const u = document.createElement('span'); u.className = 'rc-unit'; u.textContent = st.unit;
      Object.assign(u.style, { fontSize: '34px', color: 'var(--white)', marginLeft: '14px', letterSpacing: '.1em' });
      node.appendChild(u);
    }
    if (!isName && /^\d+$/.test(big) && !reduced && Number(big) > 1) {
      const n = Number(big), t0 = performance.now();
      every(30, () => { const k = Math.min(1, (performance.now() - t0) / 900); num.textContent = String(Math.round(n * (1 - (1 - k) ** 3))); });
    }
  }
  let y = big !== null ? 500 : 300;
  if (st.key === 'time_attack' && st.horseName) { rcTyped(Txt(st.horseName, 64, y, 900, 26, WHITE, undefined, { weight: 700, nowrap: true })); y += 44; }
  (st.notes ?? []).forEach((n) => { Txt(n, 64, y, 900, 22, SOFT, undefined, { weight: 500, nowrap: true }).classList.add('rc-note'); y += 38; });
  if (st.horses?.length) st.horses.forEach((h) => { rcTyped(Txt(h.horseName, 64, y, 900, 30, WHITE, undefined, { weight: 700, nowrap: true })); y += 48; });
  if (st.moments?.length) {
    st.moments.forEach((m, k) => {
      const row = el('rc-moment', 64, 290 + k * 120, 900, 104); row.dataset.kind = m.kind;
      el('rule', 0, 18, 46, 3, row);
      Txt(m.text, 64, 0, 836, 28, WHITE, row, { weight: 700, nowrap: true });
      if (m.horseName) rcTyped(Txt(m.horseName, 64, 46, 836, 20, GOLD, row, { weight: 700, nowrap: true }));
    });
  }
  if (v.sinceNote) Caption(v.sinceNote, 64, 770, undefined, 15, MUTED).classList.add('rc-since', 'tshadow');
  // controls: one CTA (次へ / 共有する), back, skip
  if (!last) {
    Cta('次へ', 1180, 780, 360, () => Recap(id, i + 1)).classList.add('rc-next');
    TextLink('最後まで', 1400, 36, 160, () => Recap(id, v.steps.length - 1)).classList.add('rc-skip');
  } else {
    Cta('共有する', 1180, 780, 360, () => RecapShare(v)).classList.add('rc-share');
    Ghost('一覧へ', 940, 790, 220, 56, Recaps, undefined, 'quiet').classList.add('rc-done');
  }
  if (i > 0) Ghost('前へ', last ? 700 : 940, 790, 220, 56, () => Recap(id, i - 1), undefined, 'quiet').classList.add('rc-back');
  Back(Recaps, 'BACK', 40, 834);
  EnToggle(1435, 124, 120, 50);
  globalThis.__muchi && (globalThis.__muchi.recap = { id, index: i, key: st.key, steps: v.steps.length, short: v.short });
}

/** The share set (REQ-RECAP-011): one card each, 「順位を隠す」 drops the rank cards; recap_share when handed to the share sheet. */
function RecapShare(v) {
  const hide = prefs.get(RC_HIDE_KEY, '0') === '1';
  const cards = v.shareCards.filter((c) => !(hide && c.rank));
  Sheet(v.title, 'ムチ一閃　/　振り返りを共有', (s, close, y) => {
    s.classList.add('rc-share-sheet'); s.dataset.hideRank = String(hide);
    const t = Btn('順位を隠す', 48, y, 260, 46, () => { prefs.set(RC_HIDE_KEY, hide ? '0' : '1'); close(); RecapShare(v); }, 'choice' + (hide ? ' on' : ''), s);
    t.classList.add('rc-hide-rank');
    Txt('共有カードに入るのは、あなたの馬の名前と数字だけです', 48, y + 62, 564, 13, SOFT, s);
    cards.forEach((c, k) => {
      const card = Card('Share card', 48, y + 96 + k * 128, 564, 116, s, c.rank ? 'var(--gold)' : 'var(--cyan)');
      card.classList.add('rc-card-share'); card.dataset.card = c.card;
      Txt('ムチ一閃', 20, 14, 200, 13, CYAN, card, { weight: 700, ls: '.2em' });
      const head = !!c.headline;
      if (head) {
        // the number and the unit as two text nodes (the unit is a server word: translated on its own in English)
        const h = Txt('', 20, 38, 240, 36, GOLD, card, { weight: 700, cls: 'num', nowrap: true });
        const hn = document.createElement('span'); hn.textContent = c.headline; h.appendChild(hn);
        if (c.unit) { const hu = document.createElement('span'); hu.textContent = c.unit; hu.style.marginLeft = '8px'; hu.style.fontSize = '24px'; h.appendChild(hu); }
      }
      if (c.horseName) rcTyped(Txt(c.horseName, head ? 230 : 20, 42, 300, 24, WHITE, card, { weight: 700, nowrap: true }));
      Txt(c.lines.join('　·　'), 20, 84, 400, 14, SOFT, card, { weight: 500, nowrap: true });
      Ghost('共有する', 430, 60, 116, 44, () => {
        L.kpi([{ name: 'recap_share', at: L.now(), props: { kind: v.kind, card: c.card, hideRank: hide } }]);
        globalThis.__muchi && (globalThis.__muchi.lastKpi = 'recap_share:' + c.card);
        toast('共有しました（アプリでは共有シートを開きます）');
      }, card, 'quiet small').classList.add('rc-share-go');
    });
  });
}

// ================================================================= round 10: 支部の応援スタンプ (REQ-TEAMFEED-*)
// The team feed on the real server rules (TeamsService / TeamCore in the browser) — fixed stamps only, no text field.
// Mirrors unity/Assets/Muchi/Game/TeamFeedModel.cs: palette with server-built unlock texts, 10 s post cooldown, cheering a
// teammate's race result (one stamp each, tap again to take it back), mute (local at once) and report (hidden at once).
// ムチ一閃 tone: photoreal paddock art, two translucent navy panels, letter-spaced cyan kickers, one skewed cyan CTA ».
let tfSelected = 'cheer';
let tfLastPost = -1e15;
const TF_INTERVAL = 10_000;
// round 18 (REQ-QCHAT-016): 支部の定型チャット in the same branch screen — the right panel switches between the stamp
// palette and the phrase picker (no text field in either); quick chat posts are rows of the same feed.
let qcCategory = 'greet';
let qcPhrase = null;
let qcChosen = {};
let qcLastPost = -1e15;
const QC_TABS = [['greet', 'あいさつ'], ['cheer', '応援'], ['team', '支部'], ['race', 'レース'], ['invite', 'さそう']];
const QC_SLOT_JA = { course: 'コース', horse: '馬', race: 'レース結果', time: 'タイムアタック', cup: 'カップ', player: '支部の仲間' };
const tfWhen = (at) => { const d = Math.max(0, L.now() - at); return d < 60e3 ? 'たった今' : d < 3600e3 ? `${Math.floor(d / 60e3)}分前` : d < 86400e3 ? `${Math.floor(d / 3600e3)}時間前` : jstDate(at).split(' ')[0]; };
function tfLine(it, label) {
  if (it.kind === 'goal' && it.goal) return `共同目標「${it.goal.label}」が${it.goal.tier}段目に到達！`;
  if (it.kind === 'race' && it.race) return `${it.displayName}さんが${it.race.mode === 'tournament' ? '大会' : 'ランク戦'}で${it.race.place === 1 ? '1着！' : it.race.place + '着'}`;
  return label(it.stampId);
}
const tfNode = (tag, cls, text) => { const n = document.createElement(tag); n.className = cls; if (text != null) n.textContent = text; return n; };
/**
 * A phrase as nodes: its words (already in the language of the request — the server builds them) and its values. A cup
 * name stays as its host typed it (.keep-ja, like §42); course / race / time values come localized from the server; a
 * katakana horse or member name is romanized in English like every name on the client (REQ-L10N-010). A blank slot is an
 * empty underlined box (no placeholder characters).
 */
function qcNodes(template, slots) {
  const wrap = tfNode('span', 'qc-text qc-scale');
  for (const part of String(template ?? '').split(/(\{\w+\})/)) {
    const m = /^\{(\w+)\}$/.exec(part);
    if (!m) { if (part) wrap.appendChild(tfNode('span', 'qc-w', part)); continue; }
    const v = slots[m[1]];
    if (v == null) { const b = tfNode('span', 'qc-blank'); b.dataset.slot = m[1]; wrap.appendChild(b); continue; }
    const n = tfNode('span', 'qc-val' + (m[1] === 'cup' ? ' keep-ja typed' : ''), v);
    n.dataset.slot = m[1];
    wrap.appendChild(n);
  }
  return wrap;
}
async function TeamFeed(mode = 'stamp') {
  const chat = mode === 'chat';
  currentScreen = () => TeamFeed(mode);
  const lang = isJa() ? 'ja' : 'en';
  const team = await L.teamDemo();
  const [cat, res, qres] = await Promise.all([L.stamps(), L.teamFeed(null, lang), L.quickChat(lang)]);
  await refresh();
  const items = res.ok ? res.value.items : [];
  const qc = qres.ok ? qres.value : null;
  const stampOf = (id) => cat.stamps.find((s) => s.id === id);
  const label = (id) => stampOf(id)?.label ?? id;
  if (!stampOf(tfSelected)?.unlocked) tfSelected = cat.stamps.find((s) => s.unlocked)?.id ?? 'cheer';
  const deleting = player.deletion?.status === 'scheduled';
  Clear(chat ? 'team-chat' : 'team-feed'); SetArt('Art/home-paddock', false); Shade('left');
  TopBar(`支部　/　${team.name}`, chat ? '定型チャット　·　決まった文だけ（自由入力はありません）' : '応援スタンプ　·　定型スタンプだけ（自由入力はありません）');
  // ① the feed (newest first): stamps, race results, goal milestones and quick chat phrases
  const feed = Glass('Team feed', 36, 134, 940, 676, undefined, .86);
  feed.classList.add('tf-feed');
  Kicker('フィード', 36, 30, feed);
  Ghost('支部員のデモ', 700, 34, 204, 50, async () => { L.setClockMs(L.now() + 11_000); await L.teamActivity(); TeamFeed(mode); }, feed, 'quiet small');
  Ghost('共同目標', 480, 34, 204, 50, () => show(TeamGoal), feed, 'small').classList.add('tf-goal-link');
  const list = el('tf-list', 0, 112, 940, 556, feed);
  list.dataset.count = items.length;
  if (!items.length) Txt(chat ? 'まだ会話はありません。あいさつから始めよう' : 'まだ何もありません。スタンプで声をかけてみよう', 36, 24, 860, 19, MUTED, list);
  const phraseOf = (id) => qc?.phrases.find((p) => p.id === id);
  for (const it of items) {
    const goal = it.kind === 'goal';
    const q = it.kind === 'qchat' ? it.qchat : null;
    const row = tfNode('div', 'tf-row' + (it.kind === 'race' || goal ? ' race' : '') + (goal ? ' goal' : '') + (q ? ' qchat' : '') + (q?.mentionsMe ? ' me' : '') + (q?.anon ? ' anon' : '') + (it.mine ? ' mine' : ''));
    row.dataset.seq = it.seq; row.dataset.kind = it.kind; row.dataset.player = it.playerId;
    if (q) row.dataset.phrase = q.phraseId;
    row.appendChild(tfNode('div', 'tf-meta qc-scale', `${goal ? '支部' : it.mine ? 'あなた' : it.displayName}　·　${tfWhen(it.at)}${q?.mentionsMe ? '　·　あなたに' : ''}`));
    if (goal) row.addEventListener('click', () => show(TeamGoal));
    const main = tfNode('div', 'tf-main');
    if (q) main.appendChild(qcNodes(phraseOf(q.phraseId)?.qchatTemplate ?? q.qchatText, Object.fromEntries(q.slots.map((s) => [s.name, s.qchatValue]))));
    else if (it.kind === 'stamp') { const b = tfNode('span', 'tf-badge', label(it.stampId)); b.dataset.asset = it.stampAsset; main.appendChild(b); }
    else main.appendChild(tfNode('span', 'tf-race', tfLine(it, label)));
    row.appendChild(main);
    const foot = tfNode('div', 'tf-foot');
    for (const r of it.reactions) foot.appendChild(tfNode('span', 'tf-react' + (r.mine ? ' mine' : ''), `${label(r.stampId)} ${r.count}`));
    if ((it.kind === 'race' || q) && !it.mine) {
      const on = it.myReaction === tfSelected;
      const cheer = tfNode('button', 'tf-cheer' + (on ? ' on' : ''), on ? '応援を取り消す' : `「${label(tfSelected)}」で応援 »`);
      cheer.disabled = deleting;
      cheer.addEventListener('click', async (e) => {
        e.stopPropagation();
        const r = await L.reactToFeed(it.seq, on ? null : tfSelected);
        if (!r.ok) { toast(r.code === 'RATE_LIMITED' ? '少し待ってから応援してください' : r.code === 'DELETION_PENDING' ? 'アカウント削除の手続き中は送れません' : r.message); return; }
        TeamFeed(mode);
      });
      foot.appendChild(cheer);
    }
    if (!it.mine && !goal) { // a goal item is the team's (no author): nothing to mute or report; a former member's phrase: report only
      // round 17 (REQ-RPT-010): the feed's mute is the one block list (undone in その他 › 通報とブロック)
      if (!q?.anon) {
        const mute = tfNode('button', 'tf-link', 'ブロック');
        mute.addEventListener('click', async (e) => { e.stopPropagation(); const r = await L.muteMember(it.playerId, true); toast(r.ok ? 'ブロックしました（その他 › 通報とブロックで戻せます）' : r.message); TeamFeed(mode); });
        foot.appendChild(mute);
      }
      // round 17 (REQ-RPT-001): the report sheet; once received, the item is also hidden for me (REQ-TEAMFEED-007).
      // Round 18 integration: a quick chat phrase is its own target (kind qchat: the server copies the phrase and its values
      // from the branch); a former member's phrase has no author to name, so it keeps the §18 feed report.
      const rep = tfNode('button', 'tf-link', '通報');
      rep.dataset.report = q ? (q.anon ? 'feed' : 'qchat') : 'player';
      rep.addEventListener('click', async (e) => {
        e.stopPropagation();
        if (q?.anon) { const r = await L.reportFeed(it.seq, 'other'); toast(r.ok ? '通報を受け付けました。ご協力ありがとうございます' : r.message); TeamFeed(mode); return; }
        const target = q ? { kind: 'qchat', ref: `${q.report.teamId}:${q.report.seq}`, text: q.qchatText } : { kind: 'player' };
        ReportSheet({ playerId: it.playerId, name: it.displayName, ...target, source: 'team_feed', after: async (cat) => { await L.reportFeed(it.seq, cat === 'harassment' ? 'harassment' : 'other'); TeamFeed(mode); } });
      });
      foot.appendChild(rep);
    }
    row.appendChild(foot);
    list.appendChild(row);
  }
  // ② the right panel: stamp palette or phrase picker (a two-way switch, no text field in either)
  const pal = Glass(chat ? 'Quick chat' : 'Stamp palette', 996, 134, 568, 560, undefined, .86);
  Kicker(chat ? '定型チャット' : 'スタンプ', 36, 30, pal);
  const sw = Ghost(chat ? 'スタンプ' : '定型チャット', 328, 22, 204, 50, () => { qcPhrase = null; qcChosen = {}; TeamFeed(chat ? 'stamp' : 'chat'); }, pal, 'small');
  sw.classList.add('tf-mode');
  if (chat) return QuickChatPanel(pal, qc, deleting);
  Txt(`${cat.stamps.filter((s) => s.unlocked).length} / ${cat.stamps.length} 解放`, 300, 72, 232, 14, SOFT, pal, { align: 'right', ls: '.12em' });
  const grid = el('tf-grid', 36, 112, 496, 420, pal);
  for (const s of cat.stamps) {
    const t = tfNode('button', 'tf-stamp' + (s.unlocked ? '' : ' locked') + (s.id === tfSelected ? ' sel' : ''));
    t.dataset.stamp = s.id; t.dataset.asset = s.asset;
    t.appendChild(tfNode('b', '', s.label));
    t.appendChild(tfNode('small', '', s.unlocked ? '' : s.unlockText));
    t.addEventListener('click', () => {
      if (!s.unlocked) { toast(s.unlockText); if (s.unlock.kind === 'cosmetic') Store('looks'); return; }
      tfSelected = s.id; TeamFeed();
    });
    grid.appendChild(t);
  }
  // ③ the one filled CTA: skewed cyan with », the 10 s rule shown on it
  const wait = Math.max(0, tfLastPost + TF_INTERVAL - L.now());
  const send = Cta(deleting ? 'アカウント削除の手続き中は送れません' : `「${label(tfSelected)}」を送る`, 996, 716, 568, async () => {
    const r = await L.postStamp(tfSelected);
    tfLastPost = L.now();
    if (!r.ok) { toast(r.code === 'RATE_LIMITED' ? 'スタンプは10秒に1回、1日50回までです' : r.code === 'STAMP_LOCKED' ? r.message : r.code === 'DELETION_PENDING' ? 'アカウント削除の手続き中は送れません' : r.message); return; }
    TeamFeed();
  }, undefined, 'tf-cta');
  if (deleting) disable(send);
  if (wait > 0) {
    disable(send);
    const sp = send.querySelector('span');
    every(250, () => {
      const w = Math.max(0, tfLastPost + TF_INTERVAL - L.now());
      if (w <= 0) { send.classList.remove('disabled'); sp.textContent = `「${label(tfSelected)}」を送る`; } else sp.textContent = `あと${Math.ceil(w / 1000)}秒で送れます`;
    });
  }
  NavBar(4);
}
/** The phrase picker (mirrors unity/Assets/Muchi/Game/QuickChatModel.cs): tabs, phrases, the slot values the server accepts. */
function QuickChatPanel(pal, qc, deleting) {
  if (!qc) { Txt('支部に入ると定型チャットを使えます', 36, 120, 496, 18, MUTED, pal); NavBar(4); return; }
  const opts = (slot) => qc.options[slot] ?? [];
  const available = (p) => p.slots.every((s) => opts(s).length > 0);
  const tabs = el('qc-tabs', 36, 104, 496, 44, pal);
  for (const [id, ja] of QC_TABS) {
    const t = tfNode('button', 'qc-tab qc-scale' + (id === qcCategory ? ' sel' : ''), ja);
    t.dataset.cat = id;
    t.addEventListener('click', () => { qcCategory = id; TeamFeed('chat'); });
    tabs.appendChild(t);
  }
  const phrases = qc.phrases.filter((p) => p.category === qcCategory);
  const chosenText = (slot) => opts(slot).find((o) => o.ref === qcChosen[slot])?.qchatValue;
  const listEl = el('qc-list', 36, 160, 496, 226, pal);
  for (const p of phrases) {
    const ok = available(p);
    const b = tfNode('button', 'qc-phrase' + (p.id === qcPhrase ? ' sel' : '') + (ok ? '' : ' off'));
    b.dataset.phrase = p.id;
    b.appendChild(qcNodes(p.qchatTemplate, p.id === qcPhrase ? Object.fromEntries(p.slots.map((s) => [s, chosenText(s)]).filter(([, v]) => v != null)) : {}));
    if (!ok) b.appendChild(tfNode('small', 'qc-why qc-scale', `選べるものがまだありません（${p.slots.filter((s) => !opts(s).length).map((s) => QC_SLOT_JA[s]).join('・')}）`));
    b.addEventListener('click', () => {
      if (!ok) { toast('選べるものがまだありません'); return; }
      if (qcPhrase !== p.id) qcChosen = {};
      qcPhrase = p.id;
      for (const s of p.slots) if (opts(s).length === 1) qcChosen[s] = opts(s)[0].ref; // the only value is chosen already
      TeamFeed('chat');
    });
    listEl.appendChild(b);
  }
  // the slot values of the selected phrase (only what the server accepts: own horses, races, records, cups, members)
  const sel = qc.phrases.find((p) => p.id === qcPhrase && p.category === qcCategory) ?? null;
  const slotsEl = el('qc-slots', 36, 398, 496, 112, pal);
  // today's count at the foot of the panel (clear of the kicker at every text size)
  Txt(`今日 ${qc.usage.postsToday} / ${qc.limits.postsPerDay}`, 232, 520, 300, 14, SOFT, pal, { align: 'right', ls: '.12em', cls: 'qc-usage' });
  if (!sel) slotsEl.appendChild(tfNode('div', 'qc-hint qc-scale', '文を選んでください'));
  for (const s of sel?.slots ?? []) {
    const row = tfNode('div', 'qc-slot');
    row.dataset.slot = s;
    row.appendChild(tfNode('div', 'qc-slot-label qc-scale', QC_SLOT_JA[s]));
    const chips = tfNode('div', 'qc-chips');
    for (const o of opts(s)) {
      const c = tfNode('button', 'qc-opt qc-scale' + (qcChosen[s] === o.ref ? ' sel' : '') + (s === 'cup' ? ' keep-ja typed' : ''), o.qchatValue);
      c.dataset.ref = o.ref;
      c.addEventListener('click', () => { qcChosen[s] = o.ref; TeamFeed('chat'); });
      chips.appendChild(c);
    }
    row.appendChild(chips);
    slotsEl.appendChild(row);
  }
  // the one filled CTA: 15 s between phrases (the server's limits are the authority)
  const until = Math.max(qcLastPost + qc.limits.postIntervalMs, qc.usage.nextPostAt);
  const wait = Math.max(0, until - L.now());
  const missing = sel ? sel.slots.some((s) => !qcChosen[s]) : true;
  const reason = deleting ? 'アカウント削除の手続き中は送れません' : qc.usage.postsToday >= qc.limits.postsPerDay ? '今日の定型チャットはここまでです' : missing ? (sel ? '空欄を選んでください' : '文を選んでください') : null;
  const send = Cta(reason ?? 'この文を送る', 996, 716, 568, async () => {
    const r = await L.postQuickChat(sel.id, Object.fromEntries(sel.slots.map((s) => [s, qcChosen[s]])));
    qcLastPost = L.now();
    if (!r.ok) { toast(r.code === 'RATE_LIMITED' ? '定型チャットは15秒に1回、1日30回までです。同じ文は続けて送れません' : r.code === 'NOT_ELIGIBLE' ? 'この内容では送れません' : r.code === 'DELETION_PENDING' ? 'アカウント削除の手続き中は送れません' : r.message); TeamFeed('chat'); return; }
    qcPhrase = null; qcChosen = {};
    TeamFeed('chat');
  }, undefined, 'tf-cta qc-cta');
  if (reason) disable(send);
  else if (wait > 0) {
    disable(send);
    const sp = send.querySelector('span');
    every(250, () => {
      const w = Math.max(0, until - L.now());
      if (w <= 0) { send.classList.remove('disabled'); sp.textContent = T('この文を送る'); } else sp.textContent = `あと${Math.ceil(w / 1000)}秒で送れます`;
    });
  }
  NavBar(4);
}
const QuickChat = () => TeamFeed('chat');

// ================================================================= round 12: プレゼントボックス (REQ-BOX-*, contracts/protocol.md §26)
// The same screen as the Unity GiftBoxModel: the box (soonest expiry first) and the 90-day history, one claim per row and
