const GIFT_SOURCE_JA = { ops_compensation: 'お詫び', ops_grant: '運営', invite: '招待', event: 'イベント', tournament: '大会', team: '支部', league: '支部対抗', season: 'シーズン', team_goal: '共同目標', exchange: '交換所' };
