    Txt('応援はレースの結果に影響しません', 36, 276, 820, 15, SOFT, c, { weight: 500, nowrap: true });
    if (wait > 0) setTimeout(() => { if (cheerSpec === st && globalThis.__muchi.screen === 'spectate') drawCheer(); }, wait + 20);
